{
  "name": "Glassman FR系列高压直流电源",
  "name_en": "Glassman FR Series high-voltage DC power supply",
  "manufacturer": "Glassman",
  "description": "这是一款单路输出的高压直流电源，可远程设定输出电压和电流、开关高压输出，并读取实际输出电压、电流、恒压/恒流工作模式及故障状态。适用于需要稳定高压偏置、电源激励或高压测试的实验室装置与实验平台。",
  "description_en": "This is a single-output high-voltage DC power supply that can be remotely controlled to set output voltage and current, enable or disable the high-voltage output, and read back measured voltage, current, operating mode, and fault status. It is used in laboratory setups that require stable high-voltage biasing, powering, or high-voltage test conditions.",
  "tag_hints": [
    "high-voltage DC power supply",
    "single-output PSU",
    "remote power control",
    "constant-voltage constant-current",
    "high-voltage biasing",
    "voltage and current readback",
    "Glassman FR Series"
  ],
  "actions": [
    {
      "action_name": "auto-current",
      "description": "获取/设置输出电流设定值",
      "description_en": "get/set the output current setpoint"
    },
    {
      "action_name": "auto-device_timeout",
      "description": "获取/设置设备端通信超时状态",
      "description_en": "get/set the instrument-side communication timeout state"
    },
    {
      "action_name": "auto-output",
      "description": "获取/设置输出开关状态",
      "description_en": "get/set the output on/off state"
    },
    {
      "action_name": "auto-query",
      "description": "发送查询命令并读取电源返回结果",
      "description_en": "send a query command and read the power supply response"
    },
    {
      "action_name": "auto-reset",
      "description": "将电源复位到默认状态",
      "description_en": "reset the power supply to its default state"
    },
    {
      "action_name": "auto-sendcmd",
      "description": "向电源发送底层命令",
      "description_en": "send a low-level command to the power supply"
    },
    {
      "action_name": "auto-set_status",
      "description": "设置输出电压、电流和输出状态",
      "description_en": "set the output voltage, current, and output state"
    },
    {
      "action_name": "auto-voltage",
      "description": "获取/设置输出电压设定值",
      "description_en": "get/set the output voltage setpoint"
    },
    {
      "action_name": "auto-channel",
      "description": "获取单路输出通道",
      "description_en": "get the single output channel"
    },
    {
      "action_name": "auto-voltage_sense",
      "description": "获取感测输出电压",
      "description_en": "get the sensed output voltage"
    },
    {
      "action_name": "auto-current_sense",
      "description": "获取感测输出电流",
      "description_en": "get the sensed output current"
    },
    {
      "action_name": "auto-mode",
      "description": "获取工作模式",
      "description_en": "get the operating mode"
    },
    {
      "action_name": "auto-fault",
      "description": "获取故障状态",
      "description_en": "get the fault status"
    },
    {
      "action_name": "auto-version",
      "description": "获取数据接口软件版本",
      "description_en": "get the data interface software revision"
    },
    {
      "action_name": "auto-get_status",
      "description": "获取输出电压、电流、模式、故障与输出状态",
      "description_en": "get the output voltage, current, mode, fault, and output status"
    }
  ]
}

